/**
 * DotPortrait — interactive dot-matrix self-portrait.
 *
 * - At rest: side-glance portrait. Hover (or tap) and the dots flow into a smile; leave and they flow back.
 * - Brushing the cursor across the dots bends them like grass; they always spring back.
 * - Subtle 3D tilt toward the cursor. Transparent background.
 * - Day: orange → lilac (top to bottom). Night: amber → lilac.
 * - Follows the site's own light/dark mode: watches <html>/<body> for a `dark`/`light` class or a
 *   `data-theme` / `data-mode` attribute; falls back to the OS setting. Pass `theme` to force one.
 *
 * Self-contained: no images, no dependencies beyond React. Dot data is embedded below.
 */
import { useEffect, useRef, type CSSProperties } from "react";

type Hex = `#${string}`;
type Theme = "light" | "dark";

export interface DotPortraitProps {
  className?: string;
  style?: CSSProperties;
  /** Force a theme. Omit to follow the site's light/dark mode. */
  theme?: Theme;
  /** Top → bottom gradient colors for light mode. */
  dayColors?: [Hex, Hex];
  /** Top → bottom gradient colors for dark mode. */
  nightColors?: [Hex, Hex];
  /** Accessible name for screen readers (not shown on screen). */
  label?: string;
}

const DAY: [Hex, Hex] = ["#FF6A1A", "#B79CFF"];
const NIGHT: [Hex, Hex] = ["#FFB238", "#B79CFF"];

// cols × rows grid, n particles; packed uint8 fields (see decode()).
const DATA = { cols: 104, rows: 129, n: 6923, b64: "" };

// ---------------------------------------------------------------- data
interface Decoded {
  COLS: number; ROWS: number; N: number;
  AX: Uint8Array; AY: Uint8Array; BX: Uint8Array; BY: Uint8Array;
  LA: Uint8Array; LB: Uint8Array; AA: Uint8Array; AB: Uint8Array;
  DA: Uint8Array; DB: Uint8Array;
  DELAY: Float32Array; SWIRL: Float32Array; LIFT: Float32Array;
  JX: Float32Array; JY: Float32Array;
}
let cache: Decoded | null = null;
function decode(): Decoded {
  if (cache) return cache;
  const { cols: COLS, rows: ROWS, n: N, b64 } = DATA;
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const f = (k: number) => bytes.subarray(k * N, (k + 1) * N);
  let seed = 11;
  const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
  const AX = f(0);
  const DELAY = new Float32Array(N), SWIRL = new Float32Array(N), LIFT = new Float32Array(N);
  const JX = new Float32Array(N), JY = new Float32Array(N);
  for (let i = 0; i < N; i++) {
    DELAY[i] = (AX[i] / COLS) * 0.65 + rnd() * 0.35;
    SWIRL[i] = (rnd() - 0.5) * 7;
    LIFT[i] = 4 + rnd() * 10;
    JX[i] = rnd() - 0.5;
    JY[i] = rnd() - 0.5;
  }
  cache = {
    COLS, ROWS, N,
    AX, AY: f(1), BX: f(2), BY: f(3), LA: f(4), LB: f(5), AA: f(6), AB: f(7), DA: f(8), DB: f(9),
    DELAY, SWIRL, LIFT, JX, JY,
  };
  return cache;
}

// ---------------------------------------------------------------- theme
function readSiteTheme(): Theme {
  for (const node of [document.documentElement, document.body]) {
    if (!node) continue;
    const attr = node.getAttribute("data-theme") || node.getAttribute("data-mode");
    if (attr === "dark" || attr === "light") return attr;
    if (node.classList.contains("dark")) return "dark";
    if (node.classList.contains("light")) return "light";
  }
  return window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
}

const hexToRgb = (h: string): [number, number, number] => {
  const s = h.replace("#", "");
  const full = s.length === 3 ? s.split("").map((c) => c + c).join("") : s;
  return [0, 2, 4].map((k) => parseInt(full.slice(k, k + 2), 16) / 255) as [number, number, number];
};
const mix3 = (a: number[], b: number[], t: number) => [0, 1, 2].map((i) => a[i] + (b[i] - a[i]) * t);

// ---------------------------------------------------------------- shaders
const VS = `
attribute vec3 aPos; attribute float aSize; attribute float aGrad;
uniform vec2 uCard; uniform vec2 uScreen; uniform float uUnit; uniform vec2 uRes;
uniform vec2 uRot; uniform float uF; uniform float uPivot;
uniform vec3 uColA, uColB;
varying vec3 vCol; varying float vEdge;
void main() {
  vec3 p = vec3(aPos.xy - uCard, aPos.z - uPivot);
  float cy = cos(uRot.y), sy = sin(uRot.y), cx = cos(uRot.x), sx = sin(uRot.x);
  vec3 q = vec3(p.x * cy + p.z * sy, p.y, -p.x * sy + p.z * cy);
  vec3 r = vec3(q.x, q.y * cx - q.z * sx, q.y * sx + q.z * cx);
  r.z += uPivot;
  float s = uF / (uF - r.z);
  vec2 scr = uScreen + r.xy * s * uUnit;
  gl_Position = vec4(scr / uRes * 2.0 - 1.0, 0.0, 1.0);
  gl_Position.y = -gl_Position.y;
  float ps = aSize * uUnit * s;
  gl_PointSize = max(ps, 0.0);
  vEdge = 1.4 / max(ps, 1.0);
  vCol = mix(uColA, uColB, clamp(aGrad, 0.0, 1.0));
}`;
const FS = `
precision mediump float;
varying vec3 vCol; varying float vEdge;
void main() {
  float d = length(gl_PointCoord - 0.5);
  float a = 1.0 - smoothstep(0.5 - vEdge, 0.5, d);
  if (a <= 0.0) discard;
  gl_FragColor = vec4(vCol * a, a);
}`;

// ---------------------------------------------------------------- component
export default function DotPortrait({
  className,
  style,
  theme,
  dayColors = DAY,
  nightColors = NIGHT,
  label = "Portrait of Gamma Zheng",
}: DotPortraitProps) {
  const wrapRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const propsRef = useRef({ theme, dayColors, nightColors });
  propsRef.current = { theme, dayColors, nightColors };

  useEffect(() => {
    const wrap = wrapRef.current!, canvas = canvasRef.current!;
    const D = decode();
    const { COLS, ROWS, N, AX, AY, BX, BY, LA, LB, AA, AB, DA, DB, DELAY, SWIRL, LIFT, JX, JY } = D;
    const CX = (COLS - 1) / 2, CY = (ROWS - 1) / 2;
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    const gl = canvas.getContext("webgl", { antialias: false, alpha: true, premultipliedAlpha: true });
    if (!gl) return;
    const sh = (type: number, src: string) => {
      const s = gl.createShader(type)!;
      gl.shaderSource(s, src);
      gl.compileShader(s);
      return s;
    };
    const prog = gl.createProgram()!;
    gl.attachShader(prog, sh(gl.VERTEX_SHADER, VS));
    gl.attachShader(prog, sh(gl.FRAGMENT_SHADER, FS));
    gl.linkProgram(prog);
    gl.useProgram(prog);
    const u = (n: string) => gl.getUniformLocation(prog, n);
    const U = {
      card: u("uCard"), screen: u("uScreen"), unit: u("uUnit"), res: u("uRes"),
      rot: u("uRot"), F: u("uF"), pivot: u("uPivot"), colA: u("uColA"), colB: u("uColB"),
    };
    gl.uniform2f(U.card, CX, CY);
    gl.uniform1f(U.F, 260);
    gl.uniform1f(U.pivot, 6);
    const aPos = gl.getAttribLocation(prog, "aPos");
    const aSize = gl.getAttribLocation(prog, "aSize");
    const aGrad = gl.getAttribLocation(prog, "aGrad");
    gl.enable(gl.BLEND);
    gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
    gl.clearColor(0, 0, 0, 0);

    const out = new Float32Array(N * 5);
    const buf = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, buf);
    gl.bufferData(gl.ARRAY_BUFFER, out.byteLength, gl.DYNAMIC_DRAW);
    gl.enableVertexAttribArray(aPos); gl.vertexAttribPointer(aPos, 3, gl.FLOAT, false, 20, 0);
    gl.enableVertexAttribArray(aSize); gl.vertexAttribPointer(aSize, 1, gl.FLOAT, false, 20, 12);
    gl.enableVertexAttribArray(aGrad); gl.vertexAttribPointer(aGrad, 1, gl.FLOAT, false, 20, 16);

    // per-dot motion state
    const ox = new Float32Array(N), oy = new Float32Array(N), oz = new Float32Array(N);
    const vx = new Float32Array(N), vy = new Float32Array(N), vz = new Float32Array(N);
    if (!reduce) {
      let s = 3;
      const r = () => (s = (s * 16807) % 2147483647) / 2147483647;
      for (let i = 0; i < N; i++) { ox[i] = (r() - 0.5) * 3; oy[i] = (r() - 0.5) * 3; oz[i] = -10 - r() * 40; }
    }

    // ---- layout
    let W = 1, H = 1, DPR = 1, unit = 1, sx = 0, sy = 0;
    const resize = () => {
      const rect = wrap.getBoundingClientRect();
      DPR = Math.min(window.devicePixelRatio || 1, 2);
      W = Math.max(1, rect.width); H = Math.max(1, rect.height);
      canvas.width = Math.round(W * DPR); canvas.height = Math.round(H * DPR);
      gl.viewport(0, 0, canvas.width, canvas.height);
      unit = Math.min(W / COLS, H / ROWS) * 0.94;   // small margin so tilt never clips
      sx = W / 2; sy = H / 2;
    };
    const ro = new ResizeObserver(resize);
    ro.observe(wrap);
    resize();
    const inCard = (x: number, y: number, m = 0) =>
      Math.abs(x - sx) <= (COLS / 2 + m) * unit && Math.abs(y - sy) <= (ROWS / 2 + m) * unit;

    // ---- theme (site-driven unless forced)
    let siteTheme: Theme = readSiteTheme();
    const mo = new MutationObserver(() => { siteTheme = readSiteTheme(); });
    const moOpts = { attributes: true, attributeFilter: ["class", "data-theme", "data-mode"] };
    mo.observe(document.documentElement, moOpts);
    if (document.body) mo.observe(document.body, moOpts);
    const mq = window.matchMedia("(prefers-color-scheme: dark)");
    const onMq = () => { siteTheme = readSiteTheme(); };
    mq.addEventListener("change", onMq);
    const wantNight = () => ((propsRef.current.theme ?? siteTheme) === "dark" ? 1 : 0);
    let night = wantNight();

    // ---- pointer
    const ptr = { x: 0, y: 0, px: 0, py: 0, vx: 0, vy: 0, on: false };
    let releaseTimer = 0;
    const local = (e: PointerEvent) => {
      const r = wrap.getBoundingClientRect();
      ptr.x = e.clientX - r.left; ptr.y = e.clientY - r.top; ptr.on = true;
    };
    const onMove = (e: PointerEvent) => local(e);
    const onDown = (e: PointerEvent) => {
      local(e); ptr.px = ptr.x; ptr.py = ptr.y;
      window.clearTimeout(releaseTimer);
    };
    const onUp = (e: PointerEvent) => {
      if (e.pointerType === "touch") releaseTimer = window.setTimeout(() => { ptr.on = false; }, 1400);
    };
    const onLeave = (e: PointerEvent) => { if (e.pointerType !== "touch") ptr.on = false; };
    const onCancel = () => { ptr.on = false; };
    wrap.addEventListener("pointermove", onMove);
    wrap.addEventListener("pointerdown", onDown);
    wrap.addEventListener("pointerup", onUp);
    wrap.addEventListener("pointerleave", onLeave);
    wrap.addEventListener("pointercancel", onCancel);

    // ---- loop
    const R = 7, R2 = R * R, K = 0.085, DAMP = 0.86, REACH = 2.2, SPREAD = 1.25;
    const ss = (t: number) => t * t * (3 - 2 * t);
    let morph = 0, rx = 0, ry = 0, time = 0, last = 0, raf = 0;
    let visible = true;

    const frame = (now: number) => {
      raf = 0;
      if (!visible || document.hidden) return;
      const dt = last ? Math.max(0.25, Math.min((now - last) / 16.667, 3)) : 1;
      last = now; time += dt / 60;

      ptr.vx += ((ptr.x - ptr.px) / dt - ptr.vx) * 0.5;
      ptr.vy += ((ptr.y - ptr.py) / dt - ptr.vy) * 0.5;
      if (!isFinite(ptr.vx) || !isFinite(ptr.vy)) { ptr.vx = 0; ptr.vy = 0; }
      ptr.px = ptr.x; ptr.py = ptr.y;

      // smile on hover
      const target = ptr.on && inCard(ptr.x, ptr.y, 2) ? 1 : 0;
      const rate = (reduce ? 3 : 0.75) * dt / 60;
      morph += Math.sign(target - morph) * Math.min(rate, Math.abs(target - morph));

      // day ↔ night crossfade
      const nt = wantNight();
      night += Math.sign(nt - night) * Math.min((reduce ? 1 : 0.05) * dt, Math.abs(nt - night));
      const { dayColors: dc, nightColors: nc } = propsRef.current;
      const cA = mix3(hexToRgb(dc[0]), hexToRgb(nc[0]), night);
      const cB = mix3(hexToRgb(dc[1]), hexToRgb(nc[1]), night);
      gl.uniform3f(U.colA, cA[0], cA[1], cA[2]);
      gl.uniform3f(U.colB, cB[0], cB[1], cB[2]);

      // brushing
      const active = ptr.on && inCard(ptr.x, ptr.y, 6);
      const mx = (ptr.x - sx) / unit + CX, my = (ptr.y - sy) / unit + CY;
      const mvx = ptr.vx / unit, mvy = ptr.vy / unit;
      const raw = Math.hypot(mvx, mvy), speed = Math.min(raw, 3);
      const dirx = raw > 1e-3 ? mvx / raw : 0, diry = raw > 1e-3 ? mvy / raw : 0;
      const damp = Math.pow(DAMP, dt), k = K * dt;

      for (let p = 0; p < N; p++) {
        let e = morph * (1 + SPREAD) - DELAY[p] * SPREAD;
        e = e < 0 ? 0 : e > 1 ? 1 : ss(e);
        const arc = Math.sin(Math.PI * e);
        const bx = AX[p] + (BX[p] - AX[p]) * e + arc * SWIRL[p];
        const by = AY[p] + (BY[p] - AY[p]) * e + arc * SWIRL[p] * 0.4;
        const bz = ((DA[p] + (DB[p] - DA[p]) * e) / 255) * 14 + arc * LIFT[p];
        const a = (AA[p] + (AB[p] - AA[p]) * e) / 255;
        const l = (LA[p] + (LB[p] - LA[p]) * e) / 255;
        // tone from dot size: on light, darker = bigger; on dark, lighter = bigger
        const sDay = 1.0 - 0.72 * Math.pow(l, 1.3);
        const sNight = 0.46 + 0.52 * Math.pow(l, 0.8);
        const size = (sDay + (sNight - sDay) * night) * a;

        let fx = -ox[p] * k, fy = -oy[p] * k, fz = -oz[p] * k;
        if (active) {
          const dx = bx + ox[p] - mx, dy = by + oy[p] - my, d2 = dx * dx + dy * dy;
          if (d2 < R2) {
            const d = Math.sqrt(d2) + 1e-4, q = 1 - d / R, w = q * q * speed * dt;
            fx += (dirx * 0.16 + (dx / d) * 0.05 + JX[p] * 0.12) * w;
            fy += (diry * 0.16 + (dy / d) * 0.05 + JY[p] * 0.12) * w;
            fz += 0.18 * w;
          }
        }
        vx[p] = (vx[p] + fx) * damp; vy[p] = (vy[p] + fy) * damp; vz[p] = (vz[p] + fz) * damp;
        ox[p] += vx[p] * dt; oy[p] += vy[p] * dt; oz[p] += vz[p] * dt;
        const ol = ox[p] * ox[p] + oy[p] * oy[p];
        if (ol > REACH * REACH) {
          const m = REACH / Math.sqrt(ol);
          ox[p] *= m; oy[p] *= m; vx[p] *= 0.6; vy[p] *= 0.6;
        }
        const o = p * 5;
        out[o] = bx + ox[p]; out[o + 1] = by + oy[p]; out[o + 2] = bz + oz[p];
        out[o + 3] = size; out[o + 4] = (AY[p] + (BY[p] - AY[p]) * e) / ROWS;
      }

      // micro 3D tilt
      let tx = 0, ty = 0;
      if (!reduce) {
        if (ptr.on) {
          const nx = Math.max(-1, Math.min(1, (ptr.x - sx) / ((COLS / 2) * unit)));
          const ny = Math.max(-1, Math.min(1, (ptr.y - sy) / ((ROWS / 2) * unit)));
          ty = nx * 0.085; tx = -ny * 0.085;
        } else {
          ty = Math.sin(time * 0.35) * 0.018;
          tx = Math.cos(time * 0.27) * 0.012;
        }
      }
      const ease = 1 - Math.pow(0.93, dt);
      rx += (tx - rx) * ease; ry += (ty - ry) * ease;

      gl.clear(gl.COLOR_BUFFER_BIT);
      gl.bufferSubData(gl.ARRAY_BUFFER, 0, out);
      gl.uniform2f(U.screen, sx * DPR, sy * DPR);
      gl.uniform1f(U.unit, unit * DPR);
      gl.uniform2f(U.res, canvas.width, canvas.height);
      gl.uniform2f(U.rot, rx, ry);
      gl.drawArrays(gl.POINTS, 0, N);
      raf = requestAnimationFrame(frame);
    };
    const start = () => {
      if (!raf && visible && !document.hidden) { last = 0; raf = requestAnimationFrame(frame); }
    };

    // pause while off screen or in a background tab
    const io = new IntersectionObserver(([entry]) => { visible = entry.isIntersecting; start(); });
    io.observe(wrap);
    const onVis = () => start();
    document.addEventListener("visibilitychange", onVis);
    start();

    return () => {
      cancelAnimationFrame(raf);
      window.clearTimeout(releaseTimer);
      ro.disconnect(); io.disconnect(); mo.disconnect();
      mq.removeEventListener("change", onMq);
      document.removeEventListener("visibilitychange", onVis);
      wrap.removeEventListener("pointermove", onMove);
      wrap.removeEventListener("pointerdown", onDown);
      wrap.removeEventListener("pointerup", onUp);
      wrap.removeEventListener("pointerleave", onLeave);
      wrap.removeEventListener("pointercancel", onCancel);
      gl.getExtension("WEBGL_lose_context")?.loseContext();
    };
  }, []);

  return (
    <div
      ref={wrapRef}
      role="img"
      aria-label={label}
      className={className}
      style={{
        position: "relative",
        width: "100%",
        aspectRatio: `${DATA.cols} / ${DATA.rows}`,
        touchAction: "pan-y",
        background: "transparent",
        ...style,
      }}
    >
      <canvas
        ref={canvasRef}
        aria-hidden="true"
        style={{ position: "absolute", inset: 0, width: "100%", height: "100%", display: "block" }}
      />
    </div>
  );
}
